using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Networking;

namespace CarrotTD {
 // Four CC0 orchestral recordings (streamed from StreamingAssets after the HUD is up, never part of the data file) plus short authored musical stingers and licensed foley.
 // A voice budget and per-event throttling keep large waves from turning into clipping noise.
 public sealed class CarrotAudio : MonoBehaviour {
  readonly Dictionary<string,AudioClip> clips=new Dictionary<string,AudioClip>();
  readonly Dictionary<string,float> lastSound=new Dictionary<string,float>();
  AudioSource musicA,musicB,interfaceVoice;readonly List<AudioSource> voices=new List<AudioSource>();readonly List<AudioClip> authored=new List<AudioClip>();readonly Dictionary<AudioSource,int> priorities=new Dictionary<AudioSource,int>();
  struct Pending{public float at,volume,pitch,gap;public string name,throttle;public int priority;}readonly List<Pending> pending=new List<Pending>();
  readonly HashSet<string> loading=new HashSet<string>();float pendingFade=1.7f;bool unlocked,muted,paused;string desired="MusicExplore",playing="";float blend=1,fadeSeconds=2.2f;bool targetA=true;float soundClock,duckFor,duck=1;Vector3? eventPosition;
  void Awake(){interfaceVoice=Source("Interface");interfaceVoice.priority=8;musicA=Source("Orchestra A");musicB=Source("Orchestra B");musicA.loop=musicB.loop=true;for(int i=0;i<14;i++)voices.Add(Source("Foley "+i));foreach(var name in new[]{"ImpactSoft","ImpactGlass","ImpactWood","ImpactMetal","FootstepGrass","FootstepSnow","Coin","Build","Page","BookOpen","Chop","Slice"}){var clip=Resources.Load<AudioClip>("Carrot/Audio/"+name);if(clip!=null)clips[name]=clip;else Debug.LogWarning("Carrot audio missing: "+name);}foreach(var family in new[]{"Nibble","Dash","Shell","Swarm","Moth","Shaman","Burrow","Crystal"})foreach(var action in new[]{"Call","Hit","Attack"})LoadVoice("Voice"+family+action);foreach(var family in new[]{"Garden","Marsh","Frost"})foreach(var action in new[]{"Roar","Growl","Hit"})LoadVoice("Voice"+family+action);clips["GardenArrival"]=Stinger("Brambleback arrival",new[]{98f,146.83f,196f},1.6f,0);clips["MarshArrival"]=Stinger("Lantern Regent arrival",new[]{164.81f,246.94f,293.66f},1.8f,1);clips["FrostArrival"]=Stinger("Crown of Winter arrival",new[]{261.63f,392f,523.25f},2.1f,2);clips["OrchardArrival"]=Stinger("Old Hollowhead arrival",new[]{110f,164.81f,207.65f},1.9f,0);clips["Victory"]=Stinger("Harvest celebration",new[]{261.63f,329.63f,392f,523.25f},2f,3);clips["Defeat"]=Stinger("A quiet retry",new[]{220f,174.61f,146.83f},1.6f,4);clips["Upgrade"]=Stinger("Blossoming upgrade",new[]{523.25f,659.25f,783.99f},.7f,3);
   // Difficulty pass cues (procedural, no new recordings): blindness, uproot, tithe, the Super merge and the three challenge-boss arrivals.
   clips["LanternSnuff"]=Stinger("Lantern snuff",new[]{392f,311.13f,233.08f},1.2f,1);clips["RootSnap"]=Stinger("Root snap",new[]{110f,82.41f},.5f,0);clips["TitheJingle"]=Stinger("Tithe jingle",new[]{783.99f,987.77f,1174.66f},.8f,3);
   clips["SuperForge"]=Stinger("Super forge",new[]{196f,293.66f,392f,587.33f},1.4f,2);clips["TornadoArrival"]=Stinger("Giant Tornado arrival",new[]{146.83f,220f,293.66f},1.8f,2);clips["ZombieArrival"]=Stinger("Zombie arrival",new[]{82.41f,123.47f,155.56f},2.2f,0);clips["EyeballArrival"]=Stinger("Unknown Eyeball arrival",new[]{233.08f,349.23f,466.16f,622.25f},2.4f,1);}
  void LoadVoice(string name){var clip=Resources.Load<AudioClip>("Carrot/Audio/"+name);if(clip!=null)clips[name]=clip;else Debug.LogWarning("Carrot voice missing: "+name);}
  AudioSource Source(string name){var go=new GameObject(name);go.transform.SetParent(transform,false);var s=go.AddComponent<AudioSource>();s.playOnAwake=false;s.spatialBlend=0;s.dopplerLevel=0;s.priority=name.StartsWith("Orchestra")?32:128;s.volume=0;return s;}
  public void SetBiome(string biome){desired="MusicExplore";playing="";if(unlocked)Transition(desired,1.7f);else EnsureMusic(desired);}
  public void Unlock(){if(unlocked)return;unlocked=true;Transition(desired,.8f);}
  public void SetMuted(bool value){muted=value;ApplyVolumes();if(muted){foreach(var v in voices)v.volume=0;if(interfaceVoice!=null)interfaceVoice.Stop();}}
  public void Duck(float seconds){duckFor=Mathf.Max(duckFor,seconds);}
  void Later(float delay,string name,float volume,float pitch,string throttle,float gap,int priority=0){pending.Add(new Pending{at=soundClock+delay,name=name,volume=volume,pitch=pitch,throttle=throttle,gap=gap,priority=priority});}
  public void Tick(float dt,bool isPaused,string phase){soundClock+=dt;for(int i=pending.Count-1;i>=0;i--){if(soundClock<pending[i].at)continue;var p=pending[i];pending.RemoveAt(i);if(!paused)Play(p.name,p.volume,p.pitch,p.throttle,p.gap,false,p.priority);}if(isPaused!=paused){paused=isPaused;foreach(var v in voices){if(paused)v.Pause();else v.UnPause();}if(paused){musicA.Pause();musicB.Pause();}else{musicA.UnPause();musicB.UnPause();}}if(paused)return;duckFor=Mathf.Max(0,duckFor-dt);duck=Mathf.MoveTowards(duck,duckFor>0?.52f:1,dt*2);blend=Mathf.Min(1,blend+dt/Mathf.Max(.1f,fadeSeconds));ApplyVolumes();if(blend>=1){var old=targetA?musicB:musicA;if(old.clip!=null)ReleaseMusic(old);}}
  void ApplyVolumes(){if(musicA==null)return;float level=muted?0:.24f*duck;float inVolume=Mathf.Sin(blend*Mathf.PI*.5f)*level,outVolume=Mathf.Cos(blend*Mathf.PI*.5f)*level;musicA.volume=targetA?inVolume:outVolume;musicB.volume=targetA?outVolume:inVolume;}
  /// <summary>Music tracks live in StreamingAssets (Ogg Vorbis, MP3 for WebKit; about 8 MB the data file no longer carries): the first request for a track downloads it and the browser decodes it; the transition starts once the clip is in.</summary>
  void EnsureMusic(string name){if(clips.ContainsKey(name)||loading.Contains(name))return;loading.Add(name);StartCoroutine(LoadMusic(name));}
  System.Collections.IEnumerator LoadMusic(string name){bool mp3=CarrotQuality.WebKit;string url=Application.streamingAssetsPath+"/Carrot/"+name+(mp3?".mp3":".ogg");using(var request=UnityWebRequestMultimedia.GetAudioClip(url,mp3?AudioType.MPEG:AudioType.OGGVORBIS)){yield return request.SendWebRequest();loading.Remove(name);if(request.result!=UnityWebRequest.Result.Success){Debug.LogWarning("Carrot music unavailable: "+name+" ("+request.error+")");yield break;}var clip=DownloadHandlerAudioClip.GetContent(request);if(clip==null){Debug.LogWarning("Carrot music failed to decode: "+name);yield break;}clip.name=name;
   // The browser decodes the MP3 asynchronously: the transition waits for the buffer (up to 20 s) so the first Play is not lost.
   float waited=0;while(clip.loadState==AudioDataLoadState.Loading&&waited<20){waited+=Time.unscaledDeltaTime;yield return null;}
   if(clip.loadState==AudioDataLoadState.Failed){Debug.LogWarning("Carrot music failed to decode: "+name);Destroy(clip);yield break;}
   clips[name]=clip;Debug.Log("CARROT_MUSIC_LOADED "+name+" seconds="+clip.length.ToString("F0")+" state="+clip.loadState+" after="+waited.ToString("F1"));if(desired==name&&playing!=name)Transition(name,pendingFade);}}
  void Transition(string name,float duration){desired=name;if(!unlocked||name==playing)return;if(!clips.TryGetValue(name,out var clip)){pendingFade=duration;EnsureMusic(name);return;}targetA=!targetA;var incoming=targetA?musicA:musicB;if(incoming.clip!=null&&incoming.clip!=clip)ReleaseMusic(incoming);else incoming.Stop();incoming.clip=clip;incoming.volume=0;incoming.pitch=1;incoming.Play();if(paused)incoming.Pause();playing=name;blend=0;fadeSeconds=duration;}
  void ReleaseMusic(AudioSource source){var clip=source.clip;source.Stop();source.clip=null;if(clip==null||clip==musicA.clip||clip==musicB.clip)return;foreach(var key in new[]{"MusicExplore","MusicGarden","MusicMarsh","MusicFrost"})if(clips.TryGetValue(key,out var cached)&&cached==clip)clips.Remove(key);Destroy(clip);}
  void Play(string name,float volume,float pitch=1,string throttle=null,float minGap=0,bool creature=false,int priority=0,Vector3? at=null){if(!unlocked||muted||paused||!clips.TryGetValue(name,out var clip))return;at=at??eventPosition;string key=throttle??name;if(lastSound.TryGetValue(key,out float last)&&soundClock-last<minGap)return;lastSound[key]=soundClock;AudioSource voice=null;int first=creature?12:0,lastIndex=creature?14:12;for(int i=first;i<lastIndex;i++)if(!voices[i].isPlaying){voice=voices[i];break;}if(voice==null&&priority>0){int lowest=priority;for(int i=first;i<lastIndex;i++){int rank=priorities.TryGetValue(voices[i],out int n)?n:0;if(rank<lowest){lowest=rank;voice=voices[i];}}}if(voice==null)return;float aggregate=0;for(int i=first;i<lastIndex;i++)if(voices[i]!=voice&&voices[i].isPlaying)aggregate+=voices[i].volume;float budget=creature?(priority>=3?.34f:.20f):.54f;volume=Mathf.Min(volume,Mathf.Max(0,budget-aggregate));if(volume<.008f)return;voice.Stop();priorities[voice]=priority;voice.clip=clip;voice.volume=Mathf.Clamp(volume,0,.46f);voice.pitch=Mathf.Clamp(pitch,.55f,1.8f);voice.spatialBlend=at.HasValue?.25f:0;voice.minDistance=18;voice.maxDistance=42;voice.rolloffMode=AudioRolloffMode.Linear;voice.transform.position=at??transform.position;voice.panStereo=at.HasValue?Mathf.Clamp(at.Value.x*.035f,-.3f,.3f):0;voice.priority=priority>=3?16:creature?100:128;voice.Play();if(priority>=3)duckFor=Mathf.Max(duckFor,1.2f);}
  public void UiSound(string kind){eventPosition=null;Unlock();if(muted)return;if(lastSound.TryGetValue("ui",out var last)&&soundClock-last<.045f)return;string key=kind=="open"?"BookOpen":kind=="close"?"Page":"ImpactSoft";if(!clips.TryGetValue(key,out var clip))return;lastSound["ui"]=soundClock;interfaceVoice.Stop();interfaceVoice.clip=clip;interfaceVoice.volume=kind=="click"?.065f:.075f;interfaceVoice.pitch=kind=="close"?.95f:1.4f;interfaceVoice.Play();}
  public void Creature(string kind,string action,Vector3 at){
   if(kind=="fragment")kind="crystal";bool boss=kind=="garden"||kind=="marsh"||kind=="frost"||kind=="orchard"||kind=="tornado"||kind=="zombie"||kind=="eyeball";
   if(boss&&action=="spawn")return;
   // The challenge bosses borrow a recorded family at a shifted pitch: the tornado howls low in the Frost voice, the zombie groans in Garden's, the eyeball shrieks high in Marsh's.
   string family;switch(kind){case "nibble":family="Nibble";break;case "dash":family="Dash";break;case "shell":family="Shell";break;case "swarm":family="Swarm";break;case "moth":family="Moth";break;case "shaman":family="Shaman";break;case "burrow":family="Burrow";break;case "crystal":family="Crystal";break;case "garden":family="Garden";break;case "marsh":family="Marsh";break;case "frost":family="Frost";break;case "orchard":family="Garden";break;case "tornado":family="Frost";break;case "zombie":family="Garden";break;case "eyeball":family="Marsh";break;default:return;}
   string suffix=boss?(action=="roar"?"Roar":action=="attack"||action=="growl"?"Growl":"Hit"):(action=="spawn"?"Call":action=="attack"?"Attack":"Hit");
   bool major=boss&&(action=="roar"||action=="growl");int priority=major?4:action=="attack"?2:action=="death"?1:0;
   if(!major&&lastSound.TryGetValue("creature-global",out var global)&&soundClock-global<.13f)return;
   float volume=major?(action=="roar"?.27f:.19f):boss?.11f:action=="spawn"?.045f:action=="attack"?.105f:action=="death"?.08f:.055f;
   float basePitch=boss?(kind=="garden"?.9f:kind=="marsh"?.94f:kind=="orchard"?.78f:kind=="tornado"?.58f:kind=="zombie"?.70f:kind=="eyeball"?1.12f:.88f):kind=="moth"?1.07f:kind=="dash"?1.04f:1;
   float variation=1+Mathf.Sin(soundClock*17+kind.Length)*(action=="hit"?.09f:.027f);float gap=action=="spawn"?1.8f:major?1.25f:action=="hit"?.40f:.30f;
   Play("Voice"+family+suffix,volume,basePitch*variation,"creature-"+kind+action,gap,true,priority,at);lastSound["creature-global"]=soundClock;
  }
  public void Handle(CarrotEvent e){eventPosition=e.position;if(e.type=="build"||e.type=="upgrade"||e.type=="bossEnter"||e.type=="victory")Unlock();float variant=1+Mathf.Sin(e.id*3.17f+soundClock*4)*.06f;switch(e.type){
   case "build":Play("Build",.28f,variant);Play("Coin",.11f,1.3f);break;
   case "upgrade":Play("Upgrade",.25f,1);Play("Build",.15f,1.15f);break;
   case "sell":case "clear":Play("Coin",.2f,variant,"reward",.08f);if(e.type=="clear")Play("Chop",.1f,.82f);break;
   case "shot":Shot(e,variant);break;
   case "impact":if(e.kind=="mortar"){Play("ImpactWood",.17f,.72f,"blast",.14f);Play("ImpactMetal",.08f,.6f,"blastmetal",.2f);Later(.08f,"ImpactSoft",.12f,.5f,"blastsoft",.14f);}else if(e.kind=="frost"){Play("ImpactGlass",.085f,1.2f,"glasshit",.14f);Play("FootstepSnow",.07f,1.4f,"frostimpact",.12f);}else if(e.kind=="prism")Play("ImpactGlass",.085f,1.2f,"glasshit",.14f);else if(e.kind=="thunder"){Play("Slice",.14f,1.25f,"thundercrack",.3f);Later(.06f,"ImpactMetal",.16f,.6f,"thunder",.3f);duckFor=Mathf.Max(duckFor,.6f);}else Play("ImpactSoft",.06f,variant,"softimpact",.075f);break;
   case "spawn":Creature(e.kind,"spawn",e.position);break;
   case "death":Creature(e.kind,"death",e.position);if(e.value>0)Later(.05f,"Coin",.09f,1.6f,"deathcoin",.1f);break;
   case "bite":Creature(e.kind,"attack",e.position);break;
   case "carrotHit":Play("Chop",.23f,1.35f,"bite",.12f,priority:3,at:e.position);Play("ImpactSoft",.12f,.8f,"bitebody",.12f,priority:3,at:e.position);break;
   // Theme map: garden and orchard bosses on MusicGarden, marsh on MusicMarsh, frost on MusicFrost; the challenges borrow them (tornado Frost, zombie Marsh, eyeball Garden) with their own authored stingers.
   case "bossEnter":{string theme=e.kind=="garden"||e.kind=="orchard"||e.kind=="eyeball"?"Garden":e.kind=="marsh"||e.kind=="zombie"?"Marsh":"Frost";Transition("Music"+theme,1.8f);string arrival=e.kind=="orchard"?"OrchardArrival":e.kind=="tornado"?"TornadoArrival":e.kind=="zombie"?"ZombieArrival":e.kind=="eyeball"?"EyeballArrival":theme+"Arrival";Play(arrival,.28f,1,priority:4);Creature(e.kind,"roar",e.position);break;}
   case "telegraph":{string bossKind=e.kind=="breath"||e.kind=="mantle"||e.kind=="shatter"||e.kind=="whiteout"?"frost":e.kind=="root"||e.kind=="bark"?"garden":e.kind=="mist"||e.kind=="summon"||e.kind=="tithe"?"marsh":e.kind=="rush"||e.kind=="heap"||e.kind=="flock"||e.kind=="dusk"?"orchard":e.kind=="gust"||e.kind=="liftoff"?"tornado":e.kind=="raise"?"zombie":e.kind=="gaze"?"eyeball":"";
    // Blind and uproot are shared casts: the growl comes from whichever boss is alive (the view passes the boss through Creature on the enemy actor); here only the windup cue plays.
    if(bossKind!="")Creature(bossKind,"growl",e.position);
    bool woody=e.kind=="root"||e.kind=="bark"||e.kind=="rush"||e.kind=="heap"||e.kind=="uproot"||e.kind=="raise",glassy=e.kind=="breath"||e.kind=="mantle"||e.kind=="whiteout"||e.kind=="gaze";
    Play(glassy?"ImpactGlass":woody?"ImpactWood":"BookOpen",.17f,e.kind=="uproot"?.55f:e.kind=="blind"||e.kind=="dusk"?.5f:.63f,"bosswindup",.5f);
    if(e.kind=="uproot")Later(.3f,"Chop",.1f,.6f,"rootcreak",.4f);break;}
   case "ability":if(SignatureSound(e))break;
    if(e.kind=="blind"||e.kind=="dusk"){Play("LanternSnuff",.3f,e.kind=="dusk"?.8f:1,"blindability",.4f,priority:3);duckFor=Mathf.Max(duckFor,Mathf.Max(1,e.value));}
    else if(e.kind=="whiteout"){Play("ImpactGlass",.26f,.5f,"iceability",.4f);Play("LanternSnuff",.18f,1.5f,"whiteout",.4f,priority:3);duckFor=Mathf.Max(duckFor,2.5f);}
    else if(e.kind=="uproot"){Play("RootSnap",.3f,e.tier>=5?1.3f:1,"uprootability",.3f,priority:3);Later(.06f,"ImpactWood",.22f,.55f,"rootability",.3f);Later(.12f,"Chop",.14f,.9f,"uprootchop",.3f);}
    else if(e.kind=="tithe"){Play("TitheJingle",.24f,1,"tithe",.4f,priority:3);Play("Coin",.14f,1.2f);}
    else if(e.kind=="gust"){Play("FootstepSnow",.2f,.6f,"gust",.4f);Play("Slice",.1f,.7f,"gustslice",.4f);}
    else if(e.kind=="liftoff"){Play("Slice",.18f,.55f,"liftoff",.4f);Later(.15f,"FootstepSnow",.14f,.5f,"liftdust",.4f);}
    else if(e.kind=="raise"){Play("BookOpen",.24f,.45f,"raise",.4f);Later(.1f,"ImpactWood",.16f,.5f,"raisewood",.4f);}
    else if(e.kind=="gaze"){Play("ImpactGlass",.22f,.9f,"gaze",.4f);Play("Slice",.1f,1.6f,"gazeslice",.4f);}
    else if(e.kind=="breath"||e.kind=="shatter"){Play("ImpactGlass",.25f,.73f,"iceability",.4f);Play("Slice",.12f,.8f);}else if(e.kind=="root"||e.kind=="bark"||e.kind=="rush"||e.kind=="heap")Play("ImpactWood",.26f,.61f,"rootability",.35f);else{Play("Page",.2f,.6f,"spellability",.4f);Play("ImpactSoft",.15f,.65f);}break;
   case "merge":Play("SuperForge",.3f,1,priority:3);Later(.08f,"Build",.2f,.9f,"forgebuild",.1f);break;
   case "mergeUndo":Play("Page",.16f,.7f,"mergeundo",.3f);Play("Coin",.1f,1.1f);break;
   case "victory":Play("Victory",.32f,priority:3);Transition("MusicExplore",3f);break;
   case "defeat":Play("Defeat",.28f,priority:3);Transition("MusicExplore",3f);break;
  }eventPosition=null;}
  bool SignatureSound(CarrotEvent e){string clip=null;float pitch=1,volume=.08f;switch(e.kind){case "seedBurst":clip="FootstepGrass";pitch=1.4f;break;case "crystallize":case "shieldBreak":clip="ImpactGlass";pitch=1.6f;break;case "burn":clip="ImpactWood";pitch=.68f;break;case "prismFocus":clip="Slice";pitch=1.7f;volume=.04f;break;case "conductive":clip="ImpactMetal";pitch=1.7f;volume=.04f;break;case "blossomBuff":clip="Upgrade";pitch=.78f;volume=.055f;break;case "gravity":clip="BookOpen";pitch=.56f;volume=.12f;break;case "rewind":clip="Page";pitch=.65f;volume=.12f;break;}if(clip==null)return false;Play(clip,volume,pitch,"signature-"+e.kind,.23f,at:e.position);return true;}
  void Shot(CarrotEvent e,float variant){
   // Super (tier 5) shots reuse the kind's cue at 0.85x pitch and 1.2x volume.
   float pv=e.tier>=5?.85f:1,vv=e.tier>=5?1.2f:1;
   switch(e.kind){case "seed":Play("FootstepGrass",.065f*vv,1.6f*variant*pv,"seed",.085f);break;case "mortar":Play("ImpactWood",.16f*vv,.64f*variant*pv,"mortar",.18f);break;case "frost":Play("FootstepSnow",.1f*vv,1.2f*variant*pv,"frost",.13f);break;case "prism":Play("ImpactGlass",.065f*vv,1.55f*pv,"prism",.15f);break;case "storm":case "thunder":Play("Slice",.08f*vv,(e.kind=="thunder"?.68f:1.25f)*pv,"electric",.15f);break;case "book":Play("Page",.10f*vv,variant*pv,"page",.2f);break;case "gravity":Play("BookOpen",.1f*vv,.57f*pv,"gravity",.3f);break;case "blossom":Play("FootstepGrass",.10f*vv,.7f*pv,"blossom",.25f);break;case "starfruit":Play("Slice",.08f*vv,1.5f*pv,"star",.15f);break;}}
  AudioClip Stinger(string name,float[] notes,float duration,int timbre){const int rate=24000;int samples=Mathf.CeilToInt(duration*rate);float[] pcm=new float[samples];for(int i=0;i<samples;i++){float t=i/(float)rate;float value=0;for(int n=0;n<notes.Length;n++){float start=n*(timbre==3?.105f:.045f),u=t-start;if(u<0)continue;float env=(1-Mathf.Exp(-u*90))*Mathf.Exp(-u*(timbre==0?2.8f:3.8f));float phase=u*notes[n]*Mathf.PI*2;float tone=Mathf.Sin(phase)+Mathf.Sin(phase*2.003f)*.27f+Mathf.Sin(phase*3.99f)*.12f;if(timbre==2||timbre==1)tone+=Mathf.Sin(phase*5.41f)*.13f;if(timbre==0)tone+=Mathf.Sin(phase*.5f)*.35f;value+=tone*env;}pcm[i]=(float)Math.Tanh(value*.24f)*Mathf.Clamp01((duration-t)*7);}var clip=AudioClip.Create(name,samples,1,rate,false);clip.SetData(pcm,0);authored.Add(clip);return clip;}
  void OnDestroy(){foreach(var clip in authored)Destroy(clip);}
 }
}
